import { Music, Palette, Pen, Target, Users, type LucideIcon } from "@omnicore-platform/ui/icons";
import type { StudioCategory } from "../types";

export interface CategoryTheme {
  /** Lucide icon component for the section header chip. */
  readonly SectionIcon: LucideIcon;
  /** Tailwind classes for the tinted chip background. Literal — no interpolation. */
  readonly chipBg: string;
  /** Tailwind classes for the icon text color. Literal — no interpolation. */
  readonly iconText: string;
}

/**
 * Typed record — one entry per StudioCategory. The TS compiler verifies
 * exhaustiveness at the Record<StudioCategory, ...> constraint.
 */
export const CATEGORY_THEME: Record<StudioCategory, CategoryTheme> = {
  profiles: {
    SectionIcon: Users,
    chipBg:   "bg-cog-blue-50 dark:bg-cog-blue-500/15",
    iconText: "text-cog-blue-600 dark:text-cog-blue-300",
  },
  content: {
    SectionIcon: Pen,
    chipBg:   "bg-cog-green-50 dark:bg-cog-green-500/15",
    iconText: "text-cog-green-600 dark:text-cog-green-300",
  },
  analysis: {
    SectionIcon: Target,
    chipBg:   "bg-cog-danger-50 dark:bg-cog-danger-500/15",
    iconText: "text-cog-danger-600 dark:text-cog-danger-300",
  },
  visual: {
    SectionIcon: Palette,
    chipBg:   "bg-cog-violet-50 dark:bg-cog-violet-500/15",
    iconText: "text-cog-violet-600 dark:text-cog-violet-300",
  },
  media: {
    SectionIcon: Music,
    chipBg:   "bg-cog-amber-50 dark:bg-cog-amber-500/15",
    iconText: "text-cog-amber-600 dark:text-cog-amber-300",
  },
};


