  { id: "content-testing",  nodeType: "test_content",     category: "content" },
  { id: "translation",      nodeType: "translation",      category: "content" },
  { id: "qr-code",          nodeType: "qr_code",          category: "content" },
  { id: "image-workspace",  nodeType: "image_workspace",  category: "visual",  isSpecial: true, featured: true },
  { id: "image-suggestions", nodeType: "image_suggestions", category: "visual" },
  { id: "storyboard-task",  nodeType: "storyboard_creator", category: "visual" },
  { id: "design-canvas",    nodeType: "design_canvas",    category: "visual",  isSpecial: true },
