const TASK_MESSAGES: Record<string, TaskMessages> = {
  "audience-profile":    { name: m.studio_task_audience_profile_name,    description: m.studio_task_audience_profile_description },
  "brand-profile":       { name: m.studio_task_brand_profile_name,       description: m.studio_task_brand_profile_description },
  "voice-profile":       { name: m.studio_task_voice_profile_name,       description: m.studio_task_voice_profile_description },
  "research-assistant":  { name: m.studio_task_research_assistant_name,  description: m.studio_task_research_assistant_description },
  "content-planner":     { name: m.studio_task_content_planner_name,     description: m.studio_task_content_planner_description },
  "content-creator":     { name: m.studio_task_content_creator_name,     description: m.studio_task_content_creator_description },
  "content-testing":     { name: m.studio_task_content_testing_name,     description: m.studio_task_content_testing_description },
  "translation":         { name: m.studio_task_translation_name,         description: m.studio_task_translation_description },
  "qr-code":             { name: m.studio_task_qr_code_name,             description: m.studio_task_qr_code_description },
  "image-workspace":     { name: m.studio_task_image_workspace_name,     description: m.studio_task_image_workspace_description },
  "image-suggestions":   { name: m.studio_task_image_suggestions_name,   description: m.studio_task_image_suggestions_description },
  "storyboard-task":     { name: m.studio_task_storyboard_task_name,     description: m.studio_task_storyboard_task_description },
  "design-canvas":       { name: m.studio_task_design_canvas_name,       description: m.studio_task_design_canvas_description },
  "text-to-speech":      { name: m.studio_task_text_to_speech_name,      description: m.studio_task_text_to_speech_description },
  "audio-to-text":       { name: m.studio_task_audio_to_text_name,       description: m.studio_task_audio_to_text_description },
  "video-to-text":       { name: m.studio_task_video_to_text_name,       description: m.studio_task_video_to_text_description },
  "segmentation":        { name: m.studio_task_segmentation_name,        description: m.studio_task_segmentation_description },
  "propaganda-analysis": { name: m.studio_task_propaganda_analysis_name, description: m.studio_task_propaganda_analysis_description },
  "character-studio":    { name: m.studio_task_character_studio_name,    description: m.studio_task_character_studio_description },
