// ─── Category label + description helpers ────────────────────────────────────

type CategoryMessages = { name: () => string; description: () => string };

const CATEGORY_MESSAGES: Record<StudioCategory, CategoryMessages> = {
  profiles: { name: m.studio_category_profiles_name, description: m.studio_category_profiles_description },
  content:  { name: m.studio_category_content_name,  description: m.studio_category_content_description },
  analysis: { name: m.studio_category_analysis_name, description: m.studio_category_analysis_description },
  visual:   { name: m.studio_category_visual_name,   description: m.studio_category_visual_description },
  media:    { name: m.studio_category_media_name,    description: m.studio_category_media_description },
};

/** Returns the localized display name for a category. */
export function categoryLabel(cat: StudioCategory): string {
  return CATEGORY_MESSAGES[cat].name();
}

/** Returns the localized one-line subtitle / description for a category. */
export function categoryDescription(cat: StudioCategory): string {
  return CATEGORY_MESSAGES[cat].description();
}



